                    ])
                    """
                }
            }
        }

        when {
            process {
                """
                input [0] = GUNZIP.out.gunzip
                input [1] = DEEPBGC_DOWNLOAD.out.db
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

